sys.path.insert(0,str(Path(__file__).resolve().parent));from build_lods import meshstats,arrays,TOTAL,OUT,SRC
bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False);source=SRC/'original-v2.glb';sourceSHA=hashlib.sha256(source.read_bytes()).hexdigest();bpy.ops.import_scene.gltf(filepath=str(source));obj=next(o for o in bpy.context.scene.objects if o.type=='MESH');before=meshstats(obj.data);mod=obj.modifiers.new('BASELINE_UNPROTECTED_RED_REPRO','DECIMATE');mod.decimate_type='COLLAPSE';mod.ratio=300000/TOTAL;mod.use_collapse_triangulate=True;mod.use_symmetry=False;bpy.context.view_layer.objects.active=obj;obj.select_set(True);bpy.ops.object.modifier_apply(modifier=mod.name);after=meshstats(obj.data);v,t,uv=arrays(obj.data);bad=np.any((uv<0)|(uv>1)|~np.isfinite(uv),axis=(1,2));examples=[]
